@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Aurora — midnight sky with drifting teal/violet light ribbons */
.theme-aurora {
  --bg: oklch(0.16 0.04 260);
  --surface: oklch(0.22 0.045 262 / 78%);
  --surface-2: oklch(0.27 0.05 264 / 82%);
  --fg: oklch(0.96 0.015 250);
  --fg-muted: oklch(0.76 0.03 250);
  --accent: oklch(0.79 0.16 175);
  --accent-fg: oklch(0.15 0.04 260);
  --accent-2: oklch(0.72 0.17 300);
  --line: oklch(0.79 0.16 175 / 26%);
  --success: oklch(0.79 0.16 165);
  --warning: oklch(0.83 0.15 88);
  --danger: oklch(0.68 0.2 18);

  --radius: 1rem;
  --radius-sm: 0.625rem;
  --radius-lg: 1.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 12px -4px oklch(0 0 0 / 50%);
  --shadow-2: 0 18px 44px -18px oklch(0.5 0.16 265 / 70%);
  --shadow-3: 0 34px 80px -28px oklch(0.5 0.16 265 / 80%);
  --glow: 0 0 46px -10px oklch(0.79 0.16 175 / 60%);

  --border-width: 1px;
  --blur-amount: 14px;

  --font-display: "Outfit", "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  background-image:
    radial-gradient(70rem 34rem at 20% -12%, oklch(0.7 0.17 175 / 42%), transparent 62%),
    radial-gradient(60rem 40rem at 88% 6%, oklch(0.62 0.19 300 / 42%), transparent 62%),
    radial-gradient(80rem 36rem at 45% 108%, oklch(0.55 0.16 230 / 45%), transparent 65%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-aurora h1,
.theme-aurora h2,
.theme-aurora h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* signature */
.theme-aurora h1 { background: linear-gradient(95deg, var(--accent), var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-aurora button:hover { box-shadow: 0 0 32px color-mix(in oklab, var(--accent) 50%, transparent); }

/* depth */
.theme-aurora thead th { color: var(--accent); font-family: var(--font-display); font-size: 0.7em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.16em; border-bottom: 1px solid var(--line); background: oklch(0.79 0.16 175 / 6%); }
.theme-aurora td { border-bottom: 1px solid oklch(0.79 0.16 175 / 12%); }
.theme-aurora tbody tr:hover { background: linear-gradient(90deg, oklch(0.79 0.16 175 / 8%), oklch(0.72 0.17 300 / 8%)); }
.theme-aurora input, .theme-aurora textarea, .theme-aurora select { background: oklch(0.19 0.04 261 / 80%); border: 1px solid var(--line); color: var(--fg); }
.theme-aurora input:focus-visible, .theme-aurora textarea:focus-visible, .theme-aurora select:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-aurora kbd { background: oklch(0.26 0.05 262); border: 1px solid oklch(0.79 0.16 175 / 35%); border-radius: 0.4em; padding: 0.1em 0.45em; font-family: var(--font-mono); font-size: 0.85em; box-shadow: 0 0 12px -4px oklch(0.79 0.16 175 / 50%); }
.theme-aurora a { color: var(--accent); text-decoration: none; background-image: linear-gradient(90deg, var(--accent), var(--accent-2)); background-repeat: no-repeat; background-size: 100% 1.5px; background-position: 0 100%; padding-bottom: 1px; }
.theme-aurora a:hover { color: oklch(0.86 0.14 175); text-shadow: 0 0 16px oklch(0.79 0.16 175 / 60%); }
.theme-aurora ::selection { background: oklch(0.72 0.17 300 / 45%); color: oklch(0.98 0.01 250); }
.theme-aurora ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-aurora ::-webkit-scrollbar-track { background: oklch(0.14 0.03 260); }
.theme-aurora ::-webkit-scrollbar-thumb { background: linear-gradient(180deg, oklch(0.79 0.16 175 / 60%), oklch(0.72 0.17 300 / 60%)); border-radius: 9999px; }
.theme-aurora ::-webkit-scrollbar-thumb:hover { background: linear-gradient(180deg, var(--accent), var(--accent-2)); }
.theme-aurora .label-caps { color: var(--accent); }
.theme-aurora .themed-border { border-color: var(--line); box-shadow: 0 0 24px -12px oklch(0.79 0.16 175 / 40%); }
.theme-aurora button:active { transform: translateY(1px); }

/* alt mode: arctic noon — pale ice sheet, the ribbons faint in a daylit sky */
.theme-aurora.alt-mode {
  --bg: oklch(0.965 0.015 230);
  --surface: oklch(1 0 0 / 78%);
  --surface-2: oklch(0.94 0.025 220 / 85%);
  --fg: oklch(0.22 0.04 260);
  --fg-muted: oklch(0.44 0.03 255);
  --accent: oklch(0.52 0.13 175);
  --accent-fg: oklch(0.97 0.01 175);
  --accent-2: oklch(0.5 0.16 300);
  --line: oklch(0.52 0.13 175 / 30%);
  --shadow-1: 0 1px 3px oklch(0.3 0.06 260 / 10%);
  --shadow-2: 0 12px 32px -14px oklch(0.4 0.12 265 / 30%);
  --shadow-3: 0 26px 60px -22px oklch(0.4 0.12 265 / 38%);
  --glow: 0 0 36px -10px oklch(0.52 0.13 175 / 45%);
  background-image:
    radial-gradient(70rem 34rem at 20% -12%, oklch(0.88 0.09 175 / 45%), transparent 62%),
    radial-gradient(60rem 40rem at 88% 6%, oklch(0.88 0.08 300 / 40%), transparent 62%);
}
.theme-aurora.alt-mode input, .theme-aurora.alt-mode textarea, .theme-aurora.alt-mode select { background: oklch(1 0 0 / 85%); }
.theme-aurora.alt-mode kbd { background: oklch(0.93 0.02 220); border-color: oklch(0.52 0.13 175 / 40%); box-shadow: 0 1px 2px oklch(0.3 0.06 260 / 15%); color: var(--fg); }
.theme-aurora.alt-mode thead th { background: oklch(0.52 0.13 175 / 7%); }
.theme-aurora.alt-mode td { border-bottom-color: oklch(0.52 0.13 175 / 16%); }
.theme-aurora.alt-mode tbody tr:hover { background: linear-gradient(90deg, oklch(0.52 0.13 175 / 8%), oklch(0.5 0.16 300 / 8%)); }
.theme-aurora.alt-mode a:hover { color: oklch(0.45 0.13 175); text-shadow: none; }
.theme-aurora.alt-mode ::selection { background: oklch(0.5 0.16 300 / 25%); color: var(--fg); }
.theme-aurora.alt-mode ::-webkit-scrollbar-track { background: oklch(0.92 0.02 225); }
.theme-aurora.alt-mode h1 { background: linear-gradient(95deg, oklch(0.5 0.13 175), oklch(0.48 0.16 300)); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
